import requests

def test_get_loyalty_catalog_authenticated_user():
    base_url = "http://localhost:8000"
    endpoint = "/api/v1/loyalty/catalog"
    url = base_url + endpoint
    token = "eyJhbGciOiJFUzI1NiIsImtpZCI6ImI4MTI2OWYxLTIxZDgtNGYyZS1iNzE5LWMyMjQwYTg0MGQ5MCIsInR5cCI6IkpXVCJ9..7tnorXc_v1GajgbKOx_eL1YOszeBUfjHR8eD_sTpsMVGd1byScCiaea2NrexKmTDL3dIlmobE5Mqry_s39Blkw"
    headers = {
        "Authorization": f"Bearer {token}",
        "Accept": "application/json"
    }
    try:
        response = requests.get(url, headers=headers, timeout=30)
    except requests.RequestException as e:
        assert False, f"Request to {url} failed: {e}"

    assert response.status_code == 200, f"Expected status code 200 but got {response.status_code}"
    try:
        json_data = response.json()
    except ValueError:
        assert False, "Response is not valid JSON"

    if isinstance(json_data, list):
        catalog_list = json_data
    elif isinstance(json_data, dict):
        # Try common keys for list
        for key in ['items', 'catalog', 'entries']:
            if key in json_data and isinstance(json_data[key], list):
                catalog_list = json_data[key]
                break
        else:
            # Fallback: no recognized list key
            assert False, "Response JSON dict missing expected list of catalog entries"
    else:
        assert False, "Response JSON is neither list nor dict"

    assert isinstance(catalog_list, list), "Catalog entries is not a list"

    for entry in catalog_list:
        assert isinstance(entry, dict), "Each catalog entry should be a dictionary"
        assert "id" in entry and entry["id"], "Catalog entry missing 'id'"
        assert "name" in entry or "description" in entry, "Catalog entry missing name or description"

test_get_loyalty_catalog_authenticated_user()